selector_to_html = {"a[href=\"FieldData.html#pyskyfire.viz.scene.FieldData\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.FieldData\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FieldData</span></span></dt><dd><p>Scalar mesh values in base SI units. NaN represents unavailable data.</p><p>Units are descriptive metadata, never conversion inputs. Association is\n<code class=\"docutils literal notranslate\"><span class=\"pre\">point</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">cell</span></code> (one value per triangle).</p></dd>", "a[href=\"SceneNode.html#pyskyfire.viz.scene.SceneNode\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.SceneNode\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SceneNode</span></span></dt><dd><p>A selectable part or group, independent of the renderer\u2019s actor layout.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tags</span></code> are free-form labels. The HTML viewer offers every tag as a group\nof the nodes carrying it, as it does every <code class=\"docutils literal notranslate\"><span class=\"pre\">metadata[\"fluid\"]</span></code> a\ncomponent recorded from its results.</p></dd>", "a[href=\"#module-pyskyfire.viz.scene\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.scene<a class=\"headerlink\" href=\"#module-pyskyfire.viz.scene\" title=\"Link to this heading\">\u00b6</a></h1><p>Renderer-independent scenes. Coordinates are metres; rotations are radians.</p>", "a[href=\"Component.html#pyskyfire.viz.scene.Component\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Component\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Component</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Protocol</span></code></p><p>Base class for protocol classes.</p><p>Protocol classes are defined as:</p><p>Such classes are primarily used with static type checkers that recognize\nstructural subtyping (static duck-typing).</p><p>For example:</p><p>See PEP 544 for details. Protocol classes decorated with\n@typing.runtime_checkable act as simple-minded runtime protocols that check\nonly the presence of given attributes, ignoring their type signatures.\nProtocol classes can be generic, they are defined as:</p></dd>", "a[href=\"Anchor.html#pyskyfire.viz.scene.Anchor\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Anchor\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Anchor</span></span></dt><dd><p>Named coordinate frame. The +x axis is the outward port direction.</p></dd>", "a[href=\"Scene.html#pyskyfire.viz.scene.Scene\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Scene</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'Pyskyfire</span> <span class=\"pre\">3D'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">color_by</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">clim</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_axes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Assemble components for desktop or standalone HTML display.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">anchor</span></code> names the added component\u2019s local anchor; <code class=\"docutils literal notranslate\"><span class=\"pre\">attach_to</span></code> is a\nworld-space Anchor. Attachment mates their outward x axes in opposition.\nIt is a one-time placement calculation, with no fluid-network constraints.\nExplicit placement and anchor placement are mutually exclusive.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tags</span></code> labels the added node, a string or an iterable of them. Nodes\nsharing a tag appear together as one group in the HTML viewer, so a\ngrouping written into the script survives regenerating the results.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">show_axes</span></code> adds a corner orientation triad marking the scene axes\n(x red, y green, z blue). It is an orientation cue only, not a measuring\ngrid: it carries no ticks and does not indicate the origin or scale.</p></dd>", "a[href=\"Transform.html#pyskyfire.viz.scene.Transform\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Transform\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Transform</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">translation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">matrix</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Rigid local-to-parent transform, using column vectors.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code> is a scipy Rotation or extrinsic xyz Euler angles in radians.\nA supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">matrix</span></code> is mutually exclusive with translation and rotation.</p></dd>", "a[href=\"MeshData.html#pyskyfire.viz.scene.MeshData\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.MeshData\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">MeshData</span></span></dt><dd><p>Surface geometry in local Cartesian coordinates; indices describe triangles.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
